/**
 * @brief Evaluates a postfix (Reverse Polish Notation) expression.
 *
 * Tokens are space-separated. Operands are integers (possibly negative).
 * Supported operators: +, -, *, /
 * Division truncates toward zero (C++ integer division).
 * Assumes the expression is always valid.
 *
 * @param tokens Vector of string tokens.
 * @return The integer result of evaluating the expression.
 */

golden_completion:
int eval_rpn(const std::vector<std::string>& tokens) {
    std::stack<int> st;
    for (const auto& tok : tokens) {
        if (tok=="+"||tok=="-"||tok=="*"||tok=="/") {
            int b = st.top(); st.pop(); int a = st.top(); st.pop();
            if (tok=="+") st.push(a+b); else if (tok=="-") st.push(a-b);
            else if (tok=="*") st.push(a*b); else st.push(a/b);
        } else { st.push(std::stoi(tok)); }
    }
    return st.top();
}

